/**
 * Spec 018 R-03: the "Kota untuk pencarian" pick-list and place matching.
 *
 * The list is a stored snapshot of DataForSEO's Google SERP locations for
 * Indonesia (cities plus Jakarta's "City Region"), regenerated by
 * scripts/dataforseo/build-places.mjs from DataForSEO's public CSV. Google is
 * asked from the chosen entry's code; ChatGPT is always asked from Indonesia.
 */
import snapshot from "./places-id.json";
import { hasWordSequence, normalizedText, words } from "./text";

export type Place = Readonly<{
  code: number;
  /** DataForSEO's own (English) name, e.g. "South Jakarta,Jakarta,Indonesia". */
  name: string;
  /** Indonesian display name, e.g. "Jakarta Selatan". */
  display: string;
  /** Regency or city that tells repeated names apart, when the list has one. */
  area: string | null;
  province: string | null;
  type: "city" | "city_region";
}>;

export const PLACE_LIST_DATE: string = snapshot.listDate;
export const PLACES: readonly Place[] = snapshot.places as Place[];

/** DataForSEO's location code for the whole country (R-03). */
export const INDONESIA_LOCATION_CODE = 2360;
export const SELURUH_INDONESIA = "Seluruh Indonesia" as const;

/** The saved search place: a list entry, or the whole country. */
export type SearchPlace = Readonly<
  | { kind: "place"; code: number; display: string }
  | { kind: "indonesia"; code: typeof INDONESIA_LOCATION_CODE }
>;

export const INDONESIA_SEARCH_PLACE: SearchPlace = {
  kind: "indonesia",
  code: INDONESIA_LOCATION_CODE,
};

const byCode = new Map(PLACES.map((place) => [place.code, place]));

export function placeByCode(code: number): Place | null {
  return byCode.get(code) ?? null;
}

/** Turns a saved place back into a list entry, refusing anything that is not
 * exactly in the snapshot (the browser never invents a place). */
export function resolveSearchPlace(value: unknown): SearchPlace | null {
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  if (record.kind === "indonesia" && record.code === INDONESIA_LOCATION_CODE)
    return INDONESIA_SEARCH_PLACE;
  if (record.kind !== "place" || typeof record.code !== "number") return null;
  const place = placeByCode(record.code);
  return place && place.display === record.display
    ? { kind: "place", code: place.code, display: place.display }
    : null;
}

const repeated = new Set(
  Object.entries(
    PLACES.reduce<Record<string, number>>((counts, place) => {
      const key = normalizedText(place.display);
      counts[key] = (counts[key] ?? 0) + 1;
      return counts;
    }, {}),
  )
    .filter(([, count]) => count > 1)
    .map(([key]) => key),
);

/** The label the pick-list shows: names that repeat (Depok, Cisarua) carry
 * their regency and province, e.g. "Depok (Cirebon, Jawa Barat)". */
export function placeLabel(place: Place): string {
  if (!repeated.has(normalizedText(place.display))) return place.display;
  const detail = [place.area, place.province].filter(Boolean).join(", ");
  return detail ? `${place.display} (${detail})` : place.display;
}

export function searchPlaceLabel(place: SearchPlace): string {
  return place.kind === "indonesia" ? SELURUH_INDONESIA : place.display;
}

/** Display name used in seeds and question text; null for the whole country. */
export function searchPlaceName(place: SearchPlace): string | null {
  return place.kind === "place" ? place.display : null;
}

const ALIASES: Readonly<Record<string, string>> = { "dki jakarta": "jakarta" };

function placeKey(input: string): string {
  const stripped = input.trim().replace(/^(kota|kabupaten|kab\.)\s+/i, "");
  const key = normalizedText(stripped);
  return ALIASES[key] ?? key;
}

/** R-03 pre-fill matching: whole names, case-insensitive, after removing only
 * a leading "Kota", "Kabupaten" or "Kab.". Compass words are part of the
 * name. Returns the single matching entry, or null when none or more than one
 * matches (the customer then picks). */
export function matchPlace(input: string): Place | null {
  const key = placeKey(input);
  if (!key) return null;
  const hits = PLACES.filter((place) => normalizedText(place.display) === key);
  return hits.length === 1 ? hits[0] : null;
}

/** Experience 2: what the field is pre-filled with, or null (customer picks).
 * Branch focus uses the branch address; brand or product focus with a local
 * or multi-area reach uses the first confirmed area that matches exactly one
 * entry. National or international reach leaves it empty. */
export function prefillSearchPlace(input: {
  focus: "brand" | "produk" | "cabang";
  locationAddress?: string;
  marketReach?: string;
  marketAreas?: readonly string[];
}): SearchPlace | null {
  const toSearchPlace = (place: Place | null): SearchPlace | null =>
    place ? { kind: "place", code: place.code, display: place.display } : null;
  if (input.focus === "cabang") {
    // Address parts from the most specific end: "…, Tebet, Jakarta Selatan".
    const parts = (input.locationAddress ?? "")
      .split(/[,\n]/)
      .map((part) => part.replace(/\d{5}/g, "").trim())
      .filter(Boolean)
      .reverse();
    for (const part of parts) {
      const place = matchPlace(part);
      if (place) return toSearchPlace(place);
    }
    return null;
  }
  if (input.marketReach !== "sekitar" && input.marketReach !== "beberapa")
    return null;
  for (const area of input.marketAreas ?? []) {
    const place = matchPlace(area);
    if (place) return toSearchPlace(place);
  }
  return null;
}

/** Place names that are also ordinary words; skipped when looking for other
 * places (R-10a step 4). The search place itself is always checked.
 * Founder-editable. */
export const ORDINARY_PLACE_WORDS: readonly string[] = [
  "batu",
  "medan",
  "palu",
  "padang",
];

const placeWords = [
  ...new Map(
    PLACES.map((place) => [
      normalizedText(place.display),
      words(place.display),
    ]),
  ).entries(),
]
  .map(([key, nameWords]) => ({ key, nameWords }))
  .sort((a, b) => b.nameWords.length - a.nameWords.length);

const isJakartaPart = (key: string) => key.startsWith("jakarta ");

/**
 * R-10a: the first place named in `text` other than the search place, or null.
 * Names are matched as consecutive whole words, longest first, without
 * overlaps, so "Tangerang Selatan" is one match and never also "Tangerang".
 * Jakarta rule: a customer in one Jakarta part may say "Jakarta" alone and the
 * other parts are other places; a "Jakarta" customer may name every part.
 * With "Seluruh Indonesia" every place named counts.
 */
export function otherPlaceIn(text: string, place: SearchPlace): string | null {
  const tokens = words(text);
  const used = new Array<boolean>(tokens.length).fill(false);
  const own = place.kind === "place" ? normalizedText(place.display) : null;
  for (const { key, nameWords } of placeWords) {
    for (let i = 0; i + nameWords.length <= tokens.length; i++) {
      if (!nameWords.every((word, j) => tokens[i + j] === word && !used[i + j]))
        continue;
      for (let j = 0; j < nameWords.length; j++) used[i + j] = true;
      if (own && key === own) continue;
      if (own && isJakartaPart(own) && key === "jakarta") continue;
      if (own === "jakarta" && isJakartaPart(key)) continue;
      if (nameWords.length === 1 && ORDINARY_PLACE_WORDS.includes(key))
        continue;
      return PLACES.find((entry) => normalizedText(entry.display) === key)!
        .display;
    }
  }
  return null;
}

/** R-10a: the question names the search place ("Jakarta" also counts for a
 * customer in one of the five Jakarta parts). */
export function namesSearchPlace(text: string, place: SearchPlace): boolean {
  if (place.kind !== "place") return false;
  const own = normalizedText(place.display);
  return (
    hasWordSequence(text, own) ||
    (isJakartaPart(own) && words(text).includes("jakarta"))
  );
}
